default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\LanManServer\Parameters' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('NullSessionPipes', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [string[]] -and $current.Length -eq 1 -and [string]::Join([string][char]0, $current) -ceq [string]::Join([string][char]0, @('')))) {
    Write-Output 'Mismatch: HKLM:\SYSTEM\CurrentControlSet\Services\LanManServer\Parameters [NullSessionPipes]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

---

{{ if and (ne .Vars.win19cis_system_role "domaincontroller") .Vars.win19cis_level_1 }}
  {{ if .Vars.win19cis_rule_2_3_10_7 }}
    {{ if ne .Vars.win19cis_system_role "domaincontroller" }}
registry:
  HKLM\SYSTEM\CurrentControlSet\Services\LanmanServer\Parameters\NullSessionPipes:
    title: "2.3.10.7 | Ensure 'Network access: Named Pipes that can be accessed anonymously' is configured (MS only) | NullSessionPipes"
    exists: true
    value: ""
    type: REG_MULTI_SZ
    meta:
      memberserver: 1
      server: 1
      CIS_ID:
        - 2.3.10.7
      NIST800-53R5:
        - IA-2(2)
    {{ end }}
  {{ end }}
{{ end }}

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\LanManServer\Parameters')) {
    New-Item -Path 'HKLM:\SYSTEM\CurrentControlSet\Services\LanManServer\Parameters' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\LanManServer\Parameters' -Name 'NullSessionPipes' -Value @('') -PropertyType MultiString -Force | Out-Null
exit 0
